syntax.mysql:
CREATE TEMPORARY TABLE tmp_pay AS
SELECT dept, SUM(salary) AS payroll FROM employees GROUP BY dept;
SELECT * FROM tmp_pay;

syntax.tsql:
SELECT dept, SUM(salary) AS payroll
INTO #tmp_pay
FROM employees GROUP BY dept;
SELECT * FROM #tmp_pay;
